actions.script:
const report = ec.search.processFeedPending(dataFeedPendingIds, stuckMinutes);
documentsIndexed = report.documentsIndexed;
documentsDeleted = report.documentsDeleted;
rowsLeft = report.rowsLeft;
rowsStuck = report.rowsStuck;
rowsPending = report.rowsPending;
if (report.stuckError) ec.message.addError(report.stuckError);
